", "inference": false}], "mechanism_hypothesis": "Pidempi toimilupa voi vahvistaa jatkuvuutta mutta myös vakiinnuttaa luvan saaneiden asemaa.", "case_limitations": "Ei mitattua näyttöä tulokkaiden syrjäyttämisestä, omistuksen keskittymisestä tai ohjelmien muutoksesta.", "gatekeepers": ["valtioneuvosto", "luvanhaltijat"], "affected_groups": ["radiotoimijat", "kuulijat"], "mechanism_ids": [214], "related_item_ids": []}, {"case_key": "knowledge_power_1976_1994_20261024:register1990", "primary_item_id": "knowledge_power_1976_1994_20261024:register1990", "reuse_existing_item": false, "title": "Rekisteripohjainen väestölaskenta muuttaa väestön kuvaamisen menetelmää", "year_start": 1990, "year_end": 1990, "theme_ids": [6, 8, 15, 26, 29], "dimension_codes": ["classification_power", "knowledge_production"], "source_ids": ["stats"], "observations": [{"observation_id": "knowledge_power_1976_1994_20261024:register1990:1", "year": 1990, "statement": "Vuoden 1990 väestölaskenta oli ensimmäinen kokonaan rekisteripohjainen laskenta.", "source_ids": ["stats"], "evidence_kind": "documented_historical_claim", "inference": false}, {"observation_id": "knowledge_power_1976_1994_20261024:register1990:2", "year": 1990, "statement": "Luotettavuustutkimus vertasi rekisteri- ja lomaketietoja; lähde korostaa, ettei ero yksin ratkaise kumman tieto on oikea.", "source_ids": ["stats"], "evidence_kind": "documented_historical_claim", "inference": false}], "mechanism_hypothesis": "Hallinnolliset luokittelusäännöt voivat tehdä väestöstä säännöllisesti kuvattavan, mutta tulos voi erota ihmisen omasta kuvauksesta.", "case_limitations": "Luokituksen ero ei itsessään osoita virhettä tai syrjintää. Laatuselosteen nykyisiä rekisterimääriä ei siirretä vuoteen 1990.", "gatekeepers": ["tilastoviranomaiset", "rekisterinpitäjät"], "affected_groups": ["väestö", "monirooliset henkilöt"], "mechanism_ids": [], "related_item_ids": []}, {"case_key": "knowledge_power_1976_1994_20261024:channels1990", "primary_item_id