innin institutionaalinen paikka voi tuoda pitkän aikavälin oletuksia parlamentaariseen arviointiin.", "case_limitations": "Ennuste ja skenaario eivät ole toteutumia; ei näyttöä tässä erässä ennakoinnin vaikuttavuudesta yksittäiseen päätökseen.", "gatekeepers": ["eduskunta", "valtioneuvosto", "asiantuntijat"], "affected_groups": ["päätöksentekijät", "kansalaiset"], "mechanism_ids": [181], "related_item_ids": []}, {"case_key": "knowledge_power_1976_1994_20261024:library1994", "primary_item_id": "knowledge_power_1976_1994_20261024:library1994", "reuse_existing_item": false, "title": "Kirjastoille määritellään tehtävä verkkopalvelujen tasapuolisessa saatavuudessa", "year_start": 1994, "year_end": 1994, "theme_ids": [4, 8, 16, 20, 26, 29], "dimension_codes": ["access", "institutional_use"], "source_ids": ["library"], "observations": [{"observation_id": "knowledge_power_1976_1994_20261024:library1994:1", "year": 1994, "statement": "Kirjastokaistan historiakuvauksen mukaan valtio antoi yleisille kirjastoille vuonna 1994 erityisen tehtävän verkkopalvelujen tasa-arvoisen saatavuuden takaajana.", "source_ids": ["library"], "evidence_kind": "documented_historical_claim", "inference": false}], "mechanism_hypothesis": "Yhteinen julkinen käyttöpaikka voi vähentää pääsyn riippuvuutta kotitalouden omista laitteista.", "case_limitations": "Kyseessä historiallisen yhteenvedon väite tehtävästä; alkuperäinen päätös tai strategia ja toteutunut kuntakohtainen saatavuus jatkoselvitettäviä. Ei oletusta internetpisteestä jokaisessa kirjastossa vuonna 1994.", "gatekeepers": ["valtio", "kunnat", "kirjastot"], "affected_groups": ["ilman omaa yhteyttä olevat ihmiset", "kirjastojen käyttäjät"], "mechanism_ids": [], "related_item_ids": []}], "limitations": ["Tapahtumafaktat ja analyyttinen mekanismihypoteesi erotetaan; syyvaikutuksen suuruutta ei lasketa.", "Lähteet ovat historiallisia asiantuntija-, viranomais- ja instituutiokuvauksia. Aikalaispäätökset ja yksilöityjen valintojen arkistoaineisto ovat pääosin jatkotyötä.", "Koulutus, näkyvyys, tiedon luotettavuus ja päätösvalta eivät ole sama asia. Akateeminen asema ei takaa yksittäisen väitteen oikeellisuutta.", "Tieto, jolla ei ollut kirjallista tai institutionaalista julkaisukanavaa, jää tässä otoksessa aliedustetuksi.", "Saamen- ja romanikieliset yhteisöt, uskonnolliset vähemmistöt, naisten oma julkaisutoiminta sekä kirkon paikalliset lukutaitokäytännöt vaativat oman täydennyksen.", "Tietosuojan, opintotuen ja Tekes-lain poiminnoissa varmennus on rajattu indeksoituun lähdeotteeseen tai säädöksen identiteettiin; alkuperäiset asiakirjat vielä tarkistettava."], "open_tasks": ["Tekesin alkuperäiset tehtävät, rahoituksen kriteerit ja saajarakenteet.", "Henkilörekisterilain alkuperäiset oikeudet ja toimeenpano.", "Kaupalliset internetpalvelut, BBS-kulttuuri, vähemmistökieliset verkostot ja osallistumisen erot.", "1990-luvun tutkimuksen tulosohjaus sekä talousasiantuntijoiden vaikutus päätöksiin.", "Kirjastojen vuoden 1994 tehtävän alkuperäinen strategia ja kuntakohtainen toteuma.", "Itsesensuurin muutos 1976–1994 ja vastakkaiset tutkimustulkinnat."], "causal_confirmation": false, "numeric_effects_created": false}$payload$::jsonb;
 e jsonb; urls text[]; d jsonb; h text; old_hash text;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext(p->>'batch_id'));
 h := md5(p::text);
 SELECT data->>'payload_md5' INTO old_hash FROM public.dataset_meta WHERE id=p->>'batch_id';
 IF old_hash IS NOT NULL THEN
  IF old_hash<>h THEN RAISE EXCEPTION 'Batch payload changed; create a new version'; END IF;
  RETURN;
 END IF;
 FOR e IN SELECT value FROM jsonb_array_elements(p->'entries') LOOP
  IF (e->>'year_start')::int<1976 OR (e->>'year_end')::int>1994 THEN RAISE EXCEPTION 'Year outside collection'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(e->'dimension_codes') x WHERE NOT (p->'taxonomy' ? x)) THEN RAISE EXCEPTION 'Unknown dimension'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(e->'source_ids') x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'sources') s WHERE s->>'source_id'=x)) THEN RAISE EXCEPTION 'Unknown source'; END IF;
  SELECT array_agg(s->>'url' ORDER BY s->>'source_id') INTO urls FROM jsonb_array_elements(p->'sources') s WHERE e->'source_ids' ? (s->>'source_id');
  IF (e->>'reuse_existing_item')::boolean THEN
   IF NOT EXISTS(SELECT 1 FROM public.items WHERE id=e->>'primary_item_id') THEN RAISE EXCEPTION 'Missing existing item %',e->>'primary_item_id'; END IF;
   UPDATE public.items SET sources=ARRAY(SELECT DISTINCT u FROM unnest(sources||urls) u ORDER BY u),updated_at=now() WHERE id=e->>'primary_item_id' AND NOT sources @> urls;
  ELSE
   INSERT INTO public.items(id,title,year_start,year_end,type,domains,phase,problem,mechanism,effects,long_effect,current_relevance,importance,confidence,sources,subtype,evidence_confidence,interpretation_confidence)
   VALUES(e->>'primary_item_id',e->>'title',(e->>'year_start')::int,(e->>'year_end')::int,'tapahtuma',ARRAY['tieto ja valta','julkisuus','koulutus'],'1976–1994',
    (SELECT string_agg(o->>'statement',' ' ORDER BY n) FROM jsonb_array_elements(e->'observations') WITH ORDINALITY x(o,n)),
    'Tulkintahypoteesi: '||(e->>'mechanism_hypothesis'),ARRAY['Dokumentoitu institutionaalinen muutos; vaikutuksen suuruutta ei ole tunnistettu.'],e->>'case_limitations','Tiedon saatavuuden, asiantuntijuuden ja vallankäytön historiallinen vertailu.',3,'kohtalainen',urls,'knowledge_power_history','kohtalainen','kehittyvä');
  END IF;
  d := e || jsonb_build_object('batch_id',p->>'batch_id','taxonomy_id',p->>'taxonomy_id','case_type','historical_knowledge_power','sources',to_jsonb(urls),'item_ids',jsonb_build_array(e->>'primary_item_id')||(e->'related_item_ids'),'limitations',(p->'limitations')||jsonb_build_array(e->>'case_limitations'),'measurement_status','qualitative_documented_case','causal_confirmation',false,'numeric_effect',null,'mechanism_link_status','hypothesis_context','population_prevalence_measured',false);
  IF EXISTS(SELECT 1 FROM public.atlas_mechanism_cases WHERE data->>'case_key'=e->>'case_key') THEN RAISE EXCEPTION 'Case already exists outside manifest'; END IF;
  INSERT INTO public.atlas_mechanism_cases(title,year_start,year_end,kind,status,published,primary_item_id,data)
   VALUES(e->>'title',(e->>'year_start')::int,(e->>'year_end')::int,'history','hypothesis',true,e->>'primary_item_id',d);
 END LOOP;
 INSERT INTO public.dataset_meta(id,data) VALUES(p->>'batch_id',p||jsonb_build_object('payload_md5',h,'imported_at',now()));
END $import$;
COMMIT;
SELECT count(*) AS cases,count(DISTINCT primary_item_id) AS linked_items,sum(jsonb_array_length(data->'observations')) AS observations,count(*) FILTER(WHERE (data->>'reuse_existing_item')::boolean) AS reused_items,count(*) FILTER(WHERE NOT (data->>'reuse_existing_item')::boolean) AS new_items FROM public.atlas_mechanism_cases WHERE data->>'batch_id'='knowledge_power_1976_1994_20261024';
